/* sega_logo_shinobi.h -- the SEGA logo screen from The Revenge of Shinobi
 * (1989, REV01): small blue gradient logo + (R), with the classic rolling
 * vertical sheen. SILENT in the original (no chant/jingle -- verified).
 * Data extracted from ROM (tiles: Nemesis at $6CBD0 via the game's own
 * decompressor algorithm; wave table $6BA12; base palette $6A9E2); map is
 * programmatic (tiles 1..48, 12x4 at plane (14,10)) like the game's $8B52.
 * GENERATED by sega_intro_shinobi/gen_shinobi_kit.py -- do not hand-edit.
 *
 * Minimal use (SGDK, H40, after VDP_init; black screen, logo pops in):
 *
 *   shinobi_logo_draw(TILE_USER_INDEX);            // tiles + map on BG_A
 *   shinobi_palroll_reset();
 *   PAL_setColors(0, shinobi_logo_cram, 16, CPU);  // logo pops in
 *   for (u16 i = 0; i < 210; i++) {                // original shows ~3.5 s
 *       VDP_waitVSync();
 *       if (shinobi_palroll_step())                // true every 4th frame
 *           PAL_setColors(0, shinobi_logo_cram, 16, CPU);
 *   }
 *   // then: cut to black, clear plane
 *
 * The animation: CRAM entries 2..10 slide backward through a 20-entry
 * triangular brightness wave (one step / 4 frames) -- the sheen rolls down
 * the letters forever (no terminal state; the game cuts it at ~3.5 s).
 * The SEGA logotype is SEGA's IP: personal homebrew only.
 */
#ifndef SEGA_LOGO_SHINOBI_H
#define SEGA_LOGO_SHINOBI_H

#include <genesis.h>

#define SHINOBI_LOGO_TILE_COUNT  49
#define SHINOBI_LOGO_HOLD_FRAMES 210   /* original on-screen time */

extern const u32 shinobi_logo_tiles[SHINOBI_LOGO_TILE_COUNT * 8];
extern u16 shinobi_logo_cram[16];      /* palette line 0 mirror */

/* Load tiles at vramBase and draw the 12x4 logo on BG_A at tile (14,10). */
void shinobi_logo_draw(u16 vramBase);

/* Reset the sheen to step 0 and fill shinobi_logo_cram with that state. */
void shinobi_palroll_reset(void);

/* Call once per frame. Advances every 4th call; returns TRUE when
 * shinobi_logo_cram changed and should be pushed to CRAM. */
u16 shinobi_palroll_step(void);

#endif
